<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Authorship\AuthorshipSubordinateResolutionService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:studium:resolve-notaries',description:'Resolve exact Notary requirements for an accepted authorship commission')]
final class StudiumResolveNotariesCommand extends Command{public function __construct(private readonly AuthorshipSubordinateResolutionService $service){parent::__construct();}protected function configure():void{$this->addArgument('acceptance-id',InputArgument::REQUIRED);}protected function execute(InputInterface $input,OutputInterface $output):int{try{$r=$this->service->resolve('studium',(string)$input->getArgument('acceptance-id'));}catch(\Throwable$e){$output->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$output->writeln('<info>NOTARY_REQUIREMENTS_RESOLVED</info> '.$r['resolution_id']);$output->writeln('Status: '.$r['status']);foreach($r['decision']['required_specializations']as$s)$output->writeln('- '.$s);$output->writeln('Construction authority: NOT GRANTED');$output->writeln('Spawning authority: NOT GRANTED');$output->writeln('Execution authority: NOT GRANTED');return self::SUCCESS;}}
